/* Decode the request of n bytes at req, which came on ch, call its handler,
 * encode the reply into rep (COMPCTL_REP_MAX bytes) and the handles it carries
 * into rhs (IDL_REP_HANDLES slots; *rhn of them). Returns the reply's
 * length: 0 means no reply (the request has no txid, or a `later`
 * handler answers it itself). No I/O; the caller sends the reply with the
 * handles, or closes them if it can't. */
static inline uint32_t compctl_dispatch_on(handle_t ch, const struct compctl_ops *ops, void *ctx,
                                           const void *req, uint32_t n, void *rep, handle_t *rhs,
                                           uint32_t *rhn)
{
    struct idl_rep_hdr *idl_h = (struct idl_rep_hdr *)rep;
    *rhn = 0;
    (void)rhs;
    if (n < sizeof(uint32_t))
        return 0;
    idl_h->txid = ((const struct idl_req_hdr *)req)->txid;
    idl_h->status = ERR_INVALID_ARGS;
    if (n < sizeof(struct idl_req_hdr))
        return sizeof(*idl_h);
    switch (((const struct idl_req_hdr *)req)->ordinal) {
    case COMPCTL_CONNECT_INPUT: {
        const struct compctl_connect_input_req *idl_q = (const struct compctl_connect_input_req *)req;
        struct compctl_connect_input_rep *idl_r = (struct compctl_connect_input_rep *)rep;
        handle_t out_source = HANDLE_INVALID;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->connect_input) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->connect_input(ctx, &out_source);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_source != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_source != HANDLE_INVALID)
                drv_handle_close(out_source);
            return sizeof(*idl_h);
        }
        rhs[0] = out_source;
        *rhn = 1;
        return sizeof(*idl_r);
    }
    case COMPCTL_BLANK: {
        const struct compctl_blank_req *idl_q = (const struct compctl_blank_req *)req;
        struct compctl_blank_rep *idl_r = (struct compctl_blank_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->blank) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->blank(ctx, idl_q->on);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case COMPCTL_NEW_CLIENT: {
        const struct compctl_new_client_req *idl_q = (const struct compctl_new_client_req *)req;
        struct compctl_new_client_rep *idl_r = (struct compctl_new_client_rep *)rep;
        handle_t out_client = HANDLE_INVALID;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->new_client) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->new_client(ctx, idl_q->level, &out_client);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_client != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_client != HANDLE_INVALID)
                drv_handle_close(out_client);
            return sizeof(*idl_h);
        }
        rhs[0] = out_client;
        *rhn = 1;
        return sizeof(*idl_r);
    }
    case COMPCTL_STATS: {
        const struct compctl_stats_req *idl_q = (const struct compctl_stats_req *)req;
        struct compctl_stats_rep *idl_r = (struct compctl_stats_rep *)rep;
        uint64_t out_paints = 0;
        uint64_t out_painted_px = 0;
        uint64_t out_last_paint_ns = 0;
        uint64_t out_worst_paint_ns = 0;
        uint32_t out_clients = 0;
        uint32_t out_surfaces = 0;
        uint32_t out_windows = 0;
        uint64_t out_connected = 0;
        uint64_t out_refused = 0;
        uint64_t out_gone_closed = 0;
        uint64_t out_gone_protocol = 0;
        uint64_t out_gone_slow = 0;
        uint32_t out_sources = 0;
        uint64_t out_keys = 0;
        uint64_t out_reserved_keys = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->stats) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->stats(ctx, &out_paints, &out_painted_px, &out_last_paint_ns, &out_worst_paint_ns, &out_clients, &out_surfaces, &out_windows, &out_connected, &out_refused, &out_gone_closed, &out_gone_protocol, &out_gone_slow, &out_sources, &out_keys, &out_reserved_keys);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->paints = out_paints;
        idl_r->painted_px = out_painted_px;
        idl_r->last_paint_ns = out_last_paint_ns;
        idl_r->worst_paint_ns = out_worst_paint_ns;
        idl_r->clients = out_clients;
        idl_r->surfaces = out_surfaces;
        idl_r->windows = out_windows;
        idl_r->connected = out_connected;
        idl_r->refused = out_refused;
        idl_r->gone_closed = out_gone_closed;
        idl_r->gone_protocol = out_gone_protocol;
        idl_r->gone_slow = out_gone_slow;
        idl_r->sources = out_sources;
        idl_r->keys = out_keys;
        idl_r->reserved_keys = out_reserved_keys;
        return sizeof(*idl_r);
    }
    case COMPCTL_SET_LAYOUT: {
        const struct compctl_set_layout_req *idl_q = (const struct compctl_set_layout_req *)req;
        struct compctl_set_layout_rep *idl_r = (struct compctl_set_layout_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->set_layout) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->set_layout(ctx, idl_q->layout);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case COMPCTL_LAYOUT_WAIT: {
        const struct compctl_layout_wait_req *idl_q = (const struct compctl_layout_wait_req *)req;
        struct compctl_layout_wait_rep *idl_r = (struct compctl_layout_wait_rep *)rep;
        uint8_t out_now = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->layout_wait) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        struct idl_txn idl_txn = { ch, idl_h->txid };
        status_t idl_st = ops->layout_wait(ctx, idl_txn, idl_q->layout, &out_now);
        /* IDL_LATER: the handler answers with compctl_reply_layout_wait. */
        if (idl_st == IDL_LATER)
            return 0;
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->now = out_now;
        return sizeof(*idl_r);
    }
    }
    idl_h->status = ERR_NOT_SUPPORTED;
    return sizeof(*idl_h);
}

/* compctl_dispatch_on without the channel (a `later` handler's txn then has none: use compctl_dispatch_on). */
static inline uint32_t compctl_dispatch(const struct compctl_ops *ops, void *ctx, const void *req, uint32_t n,
                                        void *rep, handle_t *rhs, uint32_t *rhn)
{
    return compctl_dispatch_on(HANDLE_INVALID, ops, ctx, req, n, rep, rhs, rhn);
}

/* Take the next message on ch into slot (idl_take), a slot with room for
 * the protocol's biggest request (ERR_INVALID_ARGS if it has less). The
 * reply waiting in *rep (NULL or empty: none) goes out first in the same
 * system call (idl_take_after). It never waits: ERR_SHOULD_WAIT when
 * nothing is queued. */
static inline status_t compctl_take_slot(handle_t ch, const struct idl_slot *slot,
                                         struct idl_reply *rep)
{
    if (slot->qcap < COMPCTL_REQ_MAX)
        return ERR_INVALID_ARGS;
    if (rep && rep->ch != HANDLE_INVALID)
        return idl_take_after(ch, slot, rep);
    return idl_take(ch, slot);
}

/* Run the request in slot (taken by compctl_take_slot, or found there by a
 * successor), which came on ch: as compctl_dispatch_on, its reply built
 * in slot->r and the handles that reply carries put into rhs
 * (IDL_REP_HANDLES slots; *rhn of them). A request that carried handles is
 * answered ERR_INVALID_ARGS without its handler seeing it. Returns the
 * reply's length: 0 means no reply (no txid, or a `later` handler
 * answers it itself). No I/O; the caller sends the reply with the handles,
 * or closes them if it can't. */
static inline uint32_t compctl_run_slot(handle_t ch, const struct idl_slot *slot,
                                        const struct compctl_ops *ops, void *ctx, handle_t *rhs, uint32_t *rhn)
{
    *rhn = 0;
    if (*slot->n >= sizeof(uint32_t) && *slot->nh)
        return idl_refuse(slot);
    return compctl_dispatch_on(ch, ops, ctx, slot->q, *slot->n, slot->r, rhs, rhn);
}

/* Is the method with this wire ordinal idempotent (its keyword in the
 * .idl): run again on the state its first run left, it gives the same
 * result and the same answer? A server that keeps nothing across a
 * restart may run such a request again; any other it answers with an
 * error. */
static inline bool compctl_idempotent(uint32_t ordinal)
{
    (void)ordinal;
    return false;   /* no method is marked */
}

/* Take one message off ch and answer it. OK once a message was handled
 * (its reply may still have been dropped: the client is gone, or never
 * called); otherwise drv_channel_read's status: ERR_SHOULD_WAIT when
 * nothing is queued, ERR_PEER_CLOSED when the client is gone for good. */
static inline status_t compctl_serve_one(handle_t ch, const struct compctl_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[COMPCTL_REQ_MAX];
    _Alignas(8) uint8_t idl_r[COMPCTL_REP_MAX];
    handle_t idl_hs[IDL_READ_HANDLES];
    uint32_t idl_n = 0, idl_nh = 0;
    status_t idl_st = drv_channel_read(ch, idl_q, sizeof(idl_q), &idl_n, idl_hs, IDL_READ_HANDLES,
                                       &idl_nh);
    if (idl_st == ERR_BUFFER_TOO_SMALL)
        return idl_drain(ch, idl_n, idl_nh);
    if (idl_st != OK)
        return idl_st;
    if (idl_nh) {
        idl_close_all(idl_hs, idl_nh);
        idl_reply_status(ch, idl_q, idl_n, ERR_INVALID_ARGS);
        return OK;
    }
    handle_t idl_rhs[IDL_REP_HANDLES];
    uint32_t idl_rhn = 0;
    uint32_t idl_rn = compctl_dispatch_on(ch, ops, ctx, idl_q, idl_n, idl_r, idl_rhs, &idl_rhn);
    if (!idl_rn || drv_channel_write(ch, idl_r, idl_rn, idl_rhs, idl_rhn) != OK)
        idl_close_all(idl_rhs, idl_rhn);   /* not sent: they're still ours */
    return OK;
}

/* Serve ch until the client closes it (OK), or a wait or read fails
 * (that status: ERR_CANCELED when the driver is being killed). Each reply
 * goes out in the system call that takes the next request
 * (idl_serve_next). */
static inline status_t compctl_serve(handle_t ch, const struct compctl_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[COMPCTL_REQ_MAX];
    _Alignas(8) uint8_t idl_r[COMPCTL_REP_MAX];
    handle_t idl_rhs[IDL_REP_HANDLES];
    struct idl_serve idl_s = {
        .ch = ch, .q = idl_q, .qcap = sizeof(idl_q), .r = idl_r, .rhs = idl_rhs,
    };
    for (;;) {
        status_t idl_st = idl_serve_next(&idl_s);
        if (idl_st == ERR_PEER_CLOSED)
            return OK;
        if (idl_st != OK)
            return idl_st;
        idl_s.rn = compctl_dispatch_on(ch, ops, ctx, idl_q, idl_s.n, idl_r, idl_rhs, &idl_s.rhn);
    }
}
